use digimon_dsl::{CardSpec,compile::compile,validator::{validate,ValidationContext},raw_rust_registry::StubRegistry,pack::CardPack};
fn parsed(rule:&str)->Result<CardSpec,serde_yml::Error>{serde_yml::from_str(&format!("card: PROBE-DECK\nname: Deck Rule Witness\nkind: digimon\ncolor: [white]\ncost: 3\ndp: 1000\n{rule}\n"))}
#[test] fn source_bound_rule_survives_compile_and_pack(){let id="7e9b7b400c952ebddd1fcd82464ce4afbea79c3b49076d9987196f688ad7f595";let s=parsed(&format!("deck_rule: {{max_copies: 50, evidence_observation_id: {id}}}")).expect("authored printed deck rule");validate(&s,&ValidationContext{raw_rust:&StubRegistry::empty()}).unwrap();let c=compile(&s).unwrap();let p=CardPack::new("probe",vec![c]);let p=CardPack::from_bytes(&p.to_bytes().unwrap()).unwrap();let v=serde_yml::to_value(&p.cards[0]).unwrap();assert_eq!(v["deck_rule"]["max_copies"].as_u64(),Some(50));assert_eq!(v["deck_rule"]["evidence_observation_id"].as_str(),Some(id));}
#[test] fn invalid_or_unbound_rules_are_rejected(){for rule in ["deck_rule: {max_copies: 0, evidence_observation_id: abc}","deck_rule: {max_copies: 51, evidence_observation_id: abc}","deck_rule: {max_copies: true, evidence_observation_id: abc}","deck_rule: {max_copies: 50}","deck_rule: {max_copies: 50, evidence_observation_id: abc}"]{if let Ok(s)=parsed(rule){assert!(validate(&s,&ValidationContext{raw_rust:&StubRegistry::empty()}).is_err(),"{rule}");assert!(compile(&s).is_err(),"direct compile must fail closed: {rule}");}}}
#[test] fn unspecified_rule_does_not_invent_metadata(){let c=compile(&parsed("").unwrap()).unwrap();let v=serde_yml::to_value(&c).unwrap();assert!(v["deck_rule"].is_null());}
